contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0), "to must not be zero");
        require(amount > 0, "amount must be positive");

        IERC20 mAsset = IERC20(c.depositToken());
        uint256 mAssetBalBefore = mAsset.balanceOf(address(c));

        uint256 supplyBefore = c.balanceOfToken(to);

        // approve and supply tokens from this test contract to `to`
        uint256 selfBalance = mAsset.balanceOf(address(this));
        require(selfBalance >= amount, "test contract lacks mAsset");
        mAsset.approve(address(c), amount);
        c.supplyTokenTo(amount, to);

        uint256 mAssetBalAfterSupply = mAsset.balanceOf(address(c));
        uint256 supplyAfter = c.balanceOfToken(to);

        // redeem: pull mAsset amount from `to`'s credits; bounded by the credits they now have
        uint256 credits = c.imBalances(to);
        uint256 redeemAmount = amount <= credits ? amount : credits;
        if (redeemAmount > 0) {
            c.redeemToken(redeemAmount);
        }

        uint256 mAssetBalAfterRedeem = mAsset.balanceOf(address(c));

        // General rule: supplying increases C's mAsset balance by exactly `amount`;
        // redeeming never decreases C's mAsset balance below its pre-supply value.
        assert(
            mAssetBalAfterSupply == mAssetBalBefore + amount &&
            supplyAfter >= supplyBefore + (amount > 0 ? 1 : 0) &&
            mAssetBalAfterRedeem >= mAssetBalBefore
        );
    }

    receive() external payable {}
}

