    constructor(C _c) { c = _c; }

    function run(address user, uint256 supplyAmount, uint256 redeemAmount) public {
        // ensure the deciding call is meaningful and setup performs a real supply
        require(supplyAmount > 0, "supply amount must be positive");
        require(redeemAmount <= supplyAmount, "redeem amount must not exceed supplied amount");
        require(user != address(0), "user must not be zero address");

        // route tokens into the test contract
        IERC20(c.depositToken()).safeTransferFrom(address(this), address(this), supplyAmount);

        // setup: create a credited balance for `user`
        c.supplyTokenTo(supplyAmount, user);

        // read state before the deciding call
        uint256 beforeBal = c.imBalances(user);
        require(beforeBal > 0, "setup must create a credited balance");

        // deciding call: must not revert and must not underflow the credited balance
        bool reverted;
        try c.redeemToken(redeemAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBal = c.imBalances(user);

        assert(!reverted && afterBal <= beforeBal);
    }

    receive() external payable {}
}

