contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public payable {
        require(to != address(0), "to zero");
        require(amount > 0, "amount zero");

        uint256 beforeIm = c.imBalances(address(this));
        require(beforeIm > 0, "no credits");

        uint256 beforeBal = c.mAsset().balanceOf(address(this));
        uint256 beforeRecipient = c.mAsset().balanceOf(to);
        require(beforeBal >= amount, "insufficient mAsset");

        uint256 creditsBurned = c.savings().underlyingToCredits(amount);
        require(beforeIm >= creditsBurned, "insufficient credits");

        uint256 returned = c.redeemToken(amount);

        uint256 afterIm = c.imBalances(address(this));
        uint256 afterBal = c.mAsset().balanceOf(address(this));
        uint256 afterRecipient = c.mAsset().balanceOf(to);

        assert(
            returned == afterBal - beforeBal &&
            afterIm == beforeIm - creditsBurned &&
            afterRecipient == beforeRecipient
        );
    }

    receive() external payable {}
}

