    function run(uint256 mAssetAmount, address to) public payable {
        require(mAssetAmount > 0, "amount must be positive");
        require(to != address(0), "beneficiary must not be zero");

        IMockERC20 mAsset = IMockERC20(c.depositToken());
        mAsset.mint(address(this), mAssetAmount);
        mAsset.approve(address(c), mAssetAmount);

        uint256 beforeBalanceOfToken = c.balanceOfToken(to);
        uint256 beforeAssetBalance = mAsset.balanceOf(address(c));

        c.supplyTokenTo(mAssetAmount, to);

        uint256 afterBalanceOfToken = c.balanceOfToken(to);
        uint256 afterAssetBalance = mAsset.balanceOf(address(c));

        assert(
            afterBalanceOfToken > beforeBalanceOfToken &&
            afterBalanceOfToken - beforeBalanceOfToken <= mAssetAmount &&
            afterAssetBalance > beforeAssetBalance &&
            afterAssetBalance - beforeAssetBalance <= mAssetAmount
        );
    }

    receive() external payable {}
}

interface IMockERC20 {
    function mint(address to, uint256 amount) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to) public payable {
        require(mAssetAmount > 0, "amount must be positive");
        require(to != address(0), "beneficiary must not be zero");

        address mAsset = c.depositToken();

        (bool okMint, ) = mAsset.call(abi.encodeWithSignature("mint(address,uint256)", address(this), mAssetAmount));
        require(okMint, "mint failed");

        (bool okApprove, ) = mAsset.call(abi.encodeWithSignature("approve(address,uint256)", address(c), mAssetAmount));
        require(okApprove, "approve failed");

        uint256 beforeBalanceOfToken = c.balanceOfToken(to);
        (bool okBefore, bytes memory beforeData) = mAsset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c)));
        require(okBefore, "balanceOf before failed");
        uint256 beforeAssetBalance = abi.decode(beforeData, (uint256));

        c.supplyTokenTo(mAssetAmount, to);

        uint256 afterBalanceOfToken = c.balanceOfToken(to);
        (bool okAfter, bytes memory afterData) = mAsset.staticcall(abi.encodeWithSignature("balanceOf(address)", address(c)));
        require(okAfter, "balanceOf after failed");
        uint256 afterAssetBalance = abi.decode(afterData, (uint256));

        assert(
            afterBalanceOfToken >= beforeBalanceOfToken + 1 &&
            afterBalanceOfToken - beforeBalanceOfToken <= mAssetAmount &&
            afterAssetBalance >= beforeAssetBalance &&
            afterAssetBalance - beforeAssetBalance <= mAssetAmount
        );
    }

    receive() external payable {}
}

