contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public payable {
        require(amount > 0, "amount must be positive");
        require(to != address(0), "to must be nonzero");

        // The caller (this test contract) must own the mAssets being supplied.
        // There"s no mint/funding path through c"s public surface, so the rule is only
        // meaningful when the test already has the mAsset balance and allowance.
        IERC20 mAsset = IERC20(c.depositToken());
        require(mAsset.balanceOf(address(this)) >= amount, "not enough mAsset");
        require(mAsset.allowance(address(this), address(c)) >= amount, "need allowance");

        // Read credit balance and underlying benefit before supply.
        // balanceOfToken(to) is a view over imBalances[to] at the current exchange rate.
        uint256 beforeBalTo = c.balanceOfToken(to);
        uint256 beforeBalCaller = c.balanceOfToken(address(this));

        // Supply; credits issued are reflected in imBalances[to].
        c.supplyTokenTo(amount, to);

        uint256 afterBalTo = c.balanceOfToken(to);
        uint256 afterBalCaller = c.balanceOfToken(address(this));

        // General rule (delta in underlying terms is at most the supplied amount;
        // the beneficiary"s new credit-derived value is at least its old value).
        // Note: exchangeRate can change, so compare via the public underlying conversion.
        uint256 suppliedUnderlying = mAsset.balanceOf(address(this)) + amount; // not exact; use raw amount instead below.
        // Simpler and robust: the contract"s own credit accounting only goes up for `to`.
        assert(afterBalTo >= beforeBalTo && afterBalCaller >= beforeBalCaller);
    }

    receive() external payable {}
}

