    constructor(C _c) { c = _c; }

    function run(uint256 amount, address to, uint256 exchangeRateSeed) public {
        require(to != address(0), "recipient must be nonzero");
        require(to != address(c), "recipient must not be c");
        require(exchangeRateSeed > 0, "seed exchange rate");

        // Fund this test contract with mAsset so it can transfer into c.
        // The test contract must hold mAsset; since c.mAsset() is the underlying,
        // we assume the deployer gave this test contract enough mAsset balance.
        // Only proceed if the test contract has at least `amount` mAsset.
        require(c.mAsset().balanceOf(address(this)) >= amount, "insufficient mAsset");

        uint256 creditsBefore = c.savings().balanceOf(address(c));
        uint256 recipientCreditsBefore = c.savings().creditsToUnderlying(c.savings().balanceOf(address(c)));

        // Read the recipient's credit balance in c before supplying, if any.
        uint256 recipientImBefore = c.imBalances(to);

        // Record mAsset balance of c before the supply.
        uint256 cMBalanceBefore = c.mAsset().balanceOf(address(c));

        // Perform the state-changing supply call as a top-level statement.
        c.supplyTokenTo(amount, to);

        // Read after-values.
        uint256 recipientImAfter = c.imBalances(to);
        uint256 creditsIssued = recipientImAfter - recipientImBefore;

        // The rule: supplying `amount` mAssets must increase the recipient's credits
        // by exactly the savings contract's reported depositSavings result, which
        // equals savings.balanceOf(address(c)) - before_balance.
        uint256 cCreditsBefore = creditsBefore;
        uint256 cCreditsAfter = c.savings().balanceOf(address(c));

        // The increase in c's savings credits must equal the credits credited to the recipient.
        assert(recipientImAfter >= recipientImBefore && cCreditsAfter - cCreditsBefore == creditsIssued);
    }

    receive() external payable {}
}

