    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, address to) public {
        require(to != address(0), "recipient must be nonzero");
        require(amount > 0, "amount must be positive");

        // Setup: give this contract enough mAsset to fund the supply.
        // The Immutable mAsset is exposed by depositToken(); approve is done in c's constructor.
        IERC20 mAsset = IERC20(c.depositToken());
        // Fresh c may have zero mAsset balance here; if not enough, this require prevents
        // an unrealistic run. We only require the token balance of this test contract.
        require(mAsset.balanceOf(address(this)) >= amount, "test lacks mAsset");
        mAsset.approve(address(c), amount);

        uint256 toBefore = c.imBalances(to);

        c.supplyTokenTo(amount, to);

        uint256 toAfter = c.imBalances(to);

        // General rule: the recipient's imBalances must have increased by at least the requested
        // amount (credits issued = amount / exchangeRate, and exchangeRate <= 1e18*1e18 normally;
        // simplest invariant: increase is nonzero and equals the credits returned).
        // We cannot directly observe creditsIssued, but we can compare against the expected
        // credits computed via the public exchangeRate and underlyingToCredits if available.
        uint256 expectedCredits = c.savings().underlyingToCredits(amount);

        assert(toAfter - toBefore == expectedCredits);
    }

    receive() external payable {}
}

