contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 amount) public {
        require(to != address(0), "invalid recipient");
        require(amount > 0, "amount must be positive");

        // Provide the mAsset tokens required by supplyTokenTo. The test contract must already hold them;
        // otherwise this call reverts and no assert is reached (acceptable for parameter combinations
        // where the precondition of having balance is not met).
        c.mAsset().transfer(address(c), amount);

        uint256 beforeBal = c.balanceOfToken(to);
        uint256 beforeRate = c.savings().exchangeRate();

        c.supplyTokenTo(amount, to);

        uint256 afterBal = c.balanceOfToken(to);
        uint256 afterRate = c.savings().exchangeRate();

        uint256 expectedDelta = (amount * beforeRate) / 1e18;
        uint256 actualDelta = afterBal - beforeBal;

        // The observed balance delta must equal the amount credited at the exchange rate before the call,
        // modulo integer rounding in the savings contract's internal credit calculation. If the rate changed
        // during the call (unlikely for a plain ERC4626-like savings vault), the delta may reflect the new rate;
        // hence we allow a tolerance of one unit of value per 1e18 and also accept the after-rate computation.
        uint256 expectedDeltaAfter = (amount * afterRate) / 1e18;

        assert(
            actualDelta == expectedDelta ||
            actualDelta == expectedDeltaAfter ||
            actualDelta + 1 >= expectedDelta
        );
    }
}

