contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 creditsIssued, uint256 redeemAmount) public {
        // Seed the test contract's own imBalances by supplying credited tokens.
        // The caller (this test contract) must first obtain underlying mAsset.
        // We use the public surface only: call supplyTokenTo after acquiring mAsset.
        // mAsset is a public immutable getter; savings is public immutable getter.
        // Fetch pre-state
        uint256 creditsBefore = c.imBalances(address(this));
        uint256 contractBalanceBefore = c.balanceOfToken(address(this));

        // Setup: we cannot mint mAsset directly. Instead, record the caller credit
        // via direct state observation: the only way to increase imBalances is supplyTokenTo,
        // which needs mAsset transferFrom. We instead test the redemption bound for the
        // *existing* caller credit amount. Redeem some or all of the available credits.
        // Use the public savings token attempt. If caller has zero credits, redeemToken
        // must revert because creditsBurned would underflow imBalances subtraction.
        (bool success) = false;
        try c.redeemToken(redeemAmount) {
            success = true;
        } catch {
            success = false;
        }

        uint256 creditsAfter = c.imBalances(address(this));

        // General rule: if redeemToken succeeds, credits must not increase and
        // spot check on revert bound: redemption can only succeed if requested
        // amount was redeemable against existing credits, i.e. creditsAfter <= creditsBefore.
        // Also, the test contract can never end with more credits than it started with
        // in this setup because redeemToken only burns credits.
        assert(!success || creditsAfter <= creditsBefore);
    }
}

