        uint256 creditsBefore = c.imBalances(address(this));
        uint256 balanceBefore = c.balanceOfToken(address(this));

        // Redeem some amount; it must leave a non-negative credit balance.
        uint256 actual = c.redeemToken(redeem);

        uint256 creditsAfter = c.imBalances(address(this));
        uint256 balanceAfter = c.balanceOfToken(address(this));

        // General rule: creditsAfter <= creditsBefore (no credit creation from a redeem),
        // and the reported mAsset-equivalent balance is consistent with the remaining credits.
        assert(creditsAfter <= creditsBefore);

        // The redeem must never pay out more mAsset than the caller's reported balance before,
        // since that balance is the savings-credit equivalent of the caller's credits.
        assert(actual <= balanceBefore);

        // creditsAfter plus the burned amount equals creditsBefore, accounting for the redeem.
        // Since redeemTarget is bounded by supply, no underflow should occur.
        assert(creditsAfter + (creditsBefore - creditsAfter) == creditsBefore);

        // If any credits remain, the caller's reported balance must be non-zero only if
        // the savings exchange rate is positive; otherwise both zero.
        if (creditsAfter > 0) {
            IERC20 underlying = mAsset;
            uint256 rate = 0;
            // Read exchange rate via the savings getter through c's public savings getter.
            // c.savings() is public immutable ISavingsContractV2.
            ISavingsContractV2 savings = c.savings();
            rate = savings.exchangeRate();
            assert(balanceAfter == (creditsAfter * rate) / 1e18);
        } else {
            assert(balanceAfter == 0);
        }
    }
}

