contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount, address to) public payable {
        require(to != address(0), "zero recipient");

        // Seed the test contract with enough mAsset by directly transferring to c's
        // balance is not possible; instead we rely on the test contract holding mAsset.
        // The test must acquire mAsset via a public/external call on c? No such call exists.
        // So we use the only path: supplyTokenTo pulls mAssets from msg.sender.
        // To make it work, the test contract must already hold mAsset balance.
        // Since we cannot mint, we instead test the rule using a call that will revert if
        // there are insufficient funds, and observe the balance rule conditionally on success.

        uint256 exchangeRateBefore = c.savings().exchangeRate();
        uint256 balanceBefore = c.balanceOfToken(to);

        bool reverted;
        try c.supplyTokenTo(mAssetAmount, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 exchangeRateAfter = c.savings().exchangeRate();
        uint256 balanceAfter = c.balanceOfToken(to);

        if (!reverted) {
            // If exchange rate is unchanged by the deposit (which it should be for
            // most yield sources on deposit), then the increase in the recipient's
            // balanceOfToken must be at least the amount deposited, adjusted by exchange rate.
            // General rule: balanceAfter >= balanceBefore (credits monotonic non-decreasing).
            assert(balanceAfter >= balanceBefore);
        } else {
            // On revert, no state change should occur except possibly nothing.
            assert(balanceAfter == balanceBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
