    constructor(C _c) {
        c = _c;
    }

    function run(uint256 mAssetAmount) public payable {
        require(mAssetAmount > 0, "amount must be positive");

        // Pre-state observed only through public surface
        uint256 imBalancesBefore = c.imBalances(address(this));
        uint256 mAssetBalanceBefore = c.mAsset().balanceOf(address(c));

        // The deciding call: may revert if caller has insufficient credits or liquidity
        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSignature("redeemToken(uint256)", mAssetAmount)
        );

        uint256 imBalancesAfter = c.imBalances(address(this));
        uint256 mAssetBalanceAfter = c.mAsset().balanceOf(address(c));

        uint256 mAssetsActual;
        if (success) {
            mAssetsActual = abi.decode(returndata, (uint256));
        } else {
            mAssetsActual = 0;
        }

        // General rule: after redeemToken, the caller's credit balance must not increase,
        // and the amount of mAsset actually received cannot exceed the reduction in
        // c's mAsset balance plus the caller's prior credit/underlying value.
        // Also the returned mAssetsActual must equal the observed mAsset balance decrease
        // of c when the call succeeds and no external mAsset movements occurred.
        assert(
            imBalancesAfter <= imBalancesBefore &&
            (success ? mAssetsActual <= mAssetBalanceBefore - mAssetBalanceAfter : mAssetsActual == 0)
        );
    }

    receive() external payable {}
}

