        }

        uint256 creditsAfterRedeem = c.imBalances(beneficiary);

        assert(
            (!supplyReverted && creditsAfterSupply >= creditsBefore) &&
            (supplyReverted ? creditsAfterSupply == creditsBefore : true) &&
            (!supplyReverted ? creditsAfterRedeem <= creditsAfterSupply : true) &&
            (!redeemReverted ? mAssetsActual <= redeemAmount : true)
        );
