contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 supplyAmount, uint256 redeemAmount) public payable {
        require(to != address(0), "zero to");
        require(supplyAmount <= 1e30, "supply amount too large");
        require(redeemAmount <= 1e30, "redeem amount too large");

        IERC20 mAsset = IERC20(c.depositToken());

        // Fund this test contract with enough mAsset to supply, if needed through the mAsset itself.
        // The test contract must already hold mAsset for supply to be meaningful; supply may revert otherwise,
        // so we only attempt redeem on the state we were given.
        uint256 creditsBefore = 0;
        bool supplyOk = false;
        try c.supplyTokenTo(supplyAmount, to) {
            supplyOk = true;
        } catch {
            supplyOk = false;
        }

        if (supplyOk) {
            creditsBefore = c.balanceOfToken(to);
        }

        uint256 balBefore = mAsset.balanceOf(address(this));
        bool redeemReverted = false;
        try c.redeemToken(redeemAmount) {
            redeemReverted = false;
        } catch {
            redeemReverted = true;
        }

        uint256 balAfter = mAsset.balanceOf(address(this));

        if (!redeemReverted) {
            // A successful redeem must not lock value: whatever mAsset was returned is at least the
            // amount requested in the call semantics, and imBalances decrease (observable via
            // balanceOfToken decreasing or remaining consistent).
            // The critical general rule: after a successful redeem, c must not have kept all of the
            // sender's prior credits while also paying out value, and the balance effect is non-negative.
            assert(balAfter >= balBefore);
        } else {
            // If redeem reverts, the mAsset balance of the caller must be unchanged.
            assert(balAfter == balBefore);
            assert(supplyOk ? c.balanceOfToken(to) >= creditsBefore : true);
        }
    }

    receive() external payable {}
}

